// 취약: 이름에 ' OR 1=1 -- 가 오면?
db.query(`SELECT * FROM users WHERE name = '${name}'`);

// 안전: 값은 값으로 전달한다(파라미터 바인딩)
db.query('SELECT * FROM users WHERE name = ?', [name]);

el.textContent = userInput;        // 안전 (글자로 들어간다)
el.innerHTML = userInput;          // 위험

// 꼭 HTML 을 받아야 하면 정화기(sanitizer)를 거친다

// 취약: 남의 주문 id 를 넣으면 남의 주문이 보인다
app.get('/orders/:id', (req, res) => res.json(findOrder(req.params.id)));

// 안전: 「이 사람의 것인가」를 서버에서 확인
app.get('/orders/:id', (req, res) => {
  const order = findOrder(req.params.id);
  if (!order || order.userId !== req.user.id) return res.sendStatus(404);
  res.json(order);
});
